import android.util.*;import java.io.*;import java.util.Arrays;
public final class FinishNegative{public static void main(String[]args)throws Exception{byte[] value={1,2,3};var sink=new ByteArrayOutputStream();try(var out=new Base64OutputStream(sink,Base64.DEFAULT)){out.write(value);}if(!Arrays.equals(sink.toByteArray(),"AQID".getBytes(java.nio.charset.StandardCharsets.US_ASCII)))throw new AssertionError("Original streaming empty-finish newline behavior changed");if(!Arrays.equals(Base64.encode(value,Base64.DEFAULT),"AQID\n".getBytes(java.nio.charset.StandardCharsets.US_ASCII)))throw new AssertionError("Whole-buffer encoder lost its final newline");}}
